template bitstring mw_mybit := '010'B & ? & '1'B & ? length(1) & '1'B;
     // results in the template '010*1?1'B
    // note that & ? & turns to * within the resulting bitstring as the original ? 
    // stands for a bitstring of any length
  template bitstring mw_mybit2 := '010'B & * length(2);
     // results in the template '010??'B
     // note that the ability of the AnyValueOrNone matching symbol to match omitted
     // values is lost during concatenation
  type bitstring ConstrainedBitString length(3);
     // values of this type are always exactly 3 bits long
  template ConstrainedBitString mw_mybit3 := ?;
  template bitstring mw_mybit4 := '010'B & mw_mybit3;
     // results in the template '010*'B
     // note that the type constraint of the mw_mybit3 template has no impact on the
     // concatenation operation; the AnyValue symbol without a length modifier is always
     // replaced with a single AnyElementsOrNone
  template octetstring mw_myoct1 := 'ABCD'O & 'EF'O & ? & ? length(1) & 'EF'O;
     // results in the template 'ABCDEF*?EF'O
    // note that & ? & turns to * within the resulting octetstring as the original ? 
    // stands for an octetstring of any length
  template octetstring mw_myoct2 := 'ABCD'O & ? length (2) & 'EF'O;
     // results in the template 'ABCD??EF'O 
     // (i.e. a 5 octets i.e. 10 hexadecimal digits long value)
  template octetstring mw_myoctWrong := 'ABCD'O & ? length(2) length (4);
     // causes an error, no length matching attribute shall directly follow a concatenation
  template octetstring mw_myoct3 := ('ABCD'O & ? length(2)) length (4);
     // results in the template 'ABCD??'O
  template hexstring mw_myhexPar (integer N):=
    'ABC'H & ? length(N) & 'E'H & ? length(1) & 'F'H;
  function f_myFunc() runs on MyCompType {
    var integer v_int := 3;
    var template hexstring v_hstring;
   :
   v_hstring := 'ABC'H & ? length(v_int) & 'E'H & ? length(1) & 'F'H;
     //results in the template 'ABC???E?F'H
   p.receive (mw_myhexPar(4));
     //actual content of mw_myhexPar is 'ABC????E?F'H
  }

type record of charstring RecofChar;
  type set of integer SetofInt;
  template RecofChar mw_myRecofChar := {"ABC"} & {"D?", "EF"};
     // results in the template {"ABC", "D?", "EF" }
  template SetofInt mw_mySetofInt := { 1, 2 } & ? length(2) & { 3, 4 };
     // results in the template {1, 2, * length(2), 3, 4 }
  template RecofInt mw_myRecofInt := { 1, 2 } & { * length(1..2), 3, 4 };
     // results in the template {1, 2, * length(1..2), 3, 4 }
  template RecofChar mw_myRecofCharPar (integer N):= { "ABC" } & ? & * length(N) & { "EF" };
  function myFunc2() runs on MyCompType{
    var integer v_int := 3;
    var template RecofChar v_recofChar;
   :
   v_recofChar := { "ABC" } & ? length(v_int) & { "EF" };
     //results in the template { "ABC", * length(3), "EF" }
   p.receive ( mw_myRecofCharPar(3) );
     //actual content of mw_myRecofCharPar is { "ABC", *, * length(3), "EF" }
  }

template charstring mw_mychar1 := "ABC" & "DE*" & "F?";
     // results in the template "ABCDE*F?"
     // please note that "*" and "?" denote the characters "*" and "?"
  template charstring mw_mychar2 := "ABC" & ? & "EF";
     // results in the template pattern "ABC*EF"
  template charstring mw_mychar3 := "ABC" & * length(1 .. infinity) & "EF";
     // results in the template pattern "ABC?+EF"
  template charstring mw_mychar4 := "ABC" & * length(2 .. 5) & "EF";
     // results in the template pattern "ABC?#(2,5)EF"
  template charstring mw_mychar5 := pattern "ABC" & "?EF";
     // results in the template pattern "ABC?EF"
  template charstring mw_mychar6 := (pattern "ABC") & "?EF";
     // results in the template pattern "ABC\?EF"
  template charstring mw_mycharPar (integer p_val):=
    "ABC" & ? length(p_val) & "E" & ? length(1..10) & "F";
     // the parameterized template is used inside the following function;
     // concatenation to a pattern is performed during instantiation of the
     // template when all actual parameter values as known
  function f_myFunc3() runs on MyCompType {
    var integer v_int := 3;
    var template charstring v_cstring;
   :
   v_cstring := "ABC" & ? length(v_int .. v_int + 2) & "E" & ? length(1) & "F";
     //results in the template pattern "ABC?#(3,5)E?F"
   p.receive (mw_mycharPar(4));
     //actual content of mw_mycharPar is pattern "ABC?#4E?#(1,10)F"
  }

// definitions of restricted templates
  type record ExampleType {
     integer a,
     boolean b optional
  }
  template ExampleType m_originalOmit := omit;
  template ExampleType m_originalValue := { 1, true};
  template ExampleType m_originalAny := ?;
  template(omit) ExampleType m_targetOmit := omit(m_originalOmit);
 template(omit) ExampleType m_targetValue:= omit(m_originalValue);
 template(omit) ExampleType m_targetAny := omit(m_originalAny);  // causes error

type record ExampleType {
     integer a,
     boolean b optional
  }
  template ExampleType m_example := { 1, *}; // unrestricted
  var template(present) boolean v_field := m_example.b.present; // m_field is set to ?
  v_field := m_example.b; // causes and error as assignment of an unrestricted template to 
              // a template with the present restriction is not allowed

var template charstring v_pattern := pattern "ab\?#(1,1)";
  v_pattern.value // yields "ab\?#(1,1)"
  var template charstring v_ifpresent := "abc" ifpresent;
  v_ifpresent.value // yields "abc"
  var template charstring v_any := ?;
  v_any.value // shall result in an error
